      <CheckboxGroup
        id={props.id}
        className="ed-choices"
        value={selected}
        disabled={props.disabled}
        readOnly={props.readOnly}
        onValueChange={(next) =>
          props.onChange(
            options.map((o) => o.value).filter((v) => next.includes(v)),
